mapper.select:
select * from ( SELECT log_id logId, binding_id bindingId, oper_type_id operTypeId, DATE_FORMAT( oper_time, '%Y-%m-%d %H:%i:%s' ) operTime, device_flag deviceFlag, device_sn deviceSn FROM cust_user_mach_binding_log where binding_id=#{bindingId}) temp
order by ${column} ${order}
order by operTime desc
